const TreeUtil = {
    /**
     * treeToArray
     * @description tree数据转换成Array
     * @param treeData
     * @param config
     * @param keyAttr
     */
    treeToArray(treeData, config, keyAttr = 'key') {
        // key: string;
        // title: string;
        // isLeaf: boolean;
        // children?: IAntdTreeNode[];
        // properties?: any;
        const { parentIdAttr, rootParentId } = config;
        const result = [];
        function loop(context, data, parentId) {
            for (let i = 0; i < data.length; i++) {
                const item = data[i];
                result.push({
                    ...item, // ('properties' in item ? item.properties : item),
                    // ...item.properties,
                    [parentIdAttr]: parentId,
                });
                if (item.children && Array.isArray(item.children) && item.children.length) {
                    loop(context, item.children, item[keyAttr ?? 'key']);
                }
            }
        }
        loop(result, treeData, rootParentId);
        return result.map(({ children, ...rest }) => rest);
    },
    /**
     * arrayToAntdTree - array转换成Tree
     * @param arr
     * @param config
     */
    arrayToAntdTree(arr, config) {
        const { 
        // 主键属性
        keyAttr, 
        // title属性
        titleAttr, 
        // parentId属性
        parentIdAttr, 
        // root的parentId的值
        rootParentId, } = config;
        /**
         * findNodesByParentId
         * @param arr
         * @param parentId
         * @return {*}
         */
        function findNodesByParentId(arr, parentId) {
            return arr
                .filter((item) => item[parentIdAttr] == parentId)
                .map((item) => ({
                ...item,
                title: item[titleAttr],
                key: item[keyAttr],
                // isLeaf: true,
                children: [],
                properties: { ...item },
            }));
        }
        /**
         * Recursion
         * @constructor
         */
        function Recursion(node) {
            node.children = findNodesByParentId(arr, node.properties[keyAttr]);
            node.isLeaf = 'isLeaf' in node ? node.isLeaf : !node.children.length;
            if (node.isLeaf) {
                delete node.children;
            }
            (node.children || []).forEach((node) => {
                Recursion(node);
            });
        }
        const roots = findNodesByParentId(arr, rootParentId);
        roots.forEach((root) => {
            Recursion(root);
        });
        return roots;
    },
    /**
     * arrayToAntdTreeSelect - array转换成TreeSelect
     * @param arr
     * @param config
     */
    arrayToAntdTreeSelect(arr, config) {
        const { keyAttr, titleAttr, rootParentId, parentIdAttr } = config;
        /**
         * findNodesByParentId
         * @param arr
         * @param parentId
         * @return {*}
         */
        function findNodesByParentId(arr, parentId) {
            return arr
                .filter((item) => item[parentIdAttr] == parentId)
                .map((item) => ({
                ...item,
                key: item[keyAttr],
                title: item[titleAttr],
                value: item[keyAttr],
                // isLeaf: true,
                children: [],
                properties: { ...item },
            }));
        }
        /**
         * Recursion
         * @constructor
         */
        function Recursion(node) {
            node.children = findNodesByParentId(arr, node.properties[keyAttr]);
            node.isLeaf = 'isLeaf' in node ? node.isLeaf : !node.children.length;
            if (node.isLeaf) {
                delete node.children;
            }
            (node.children || []).forEach((node) => {
                Recursion(node);
            });
        }
        const roots = findNodesByParentId(arr, rootParentId);
        roots.forEach((root) => {
            Recursion(root);
        });
        return roots;
    },
    /**
     * getAncestor - 获取祖先
     * @param data
     * @param node
     * @param config
     */
    getAncestor(data, node, config) {
        const result = [];
        let curNode = node;
        while (curNode && curNode[config.parentIdAttr] != config.rootParentId) {
            const item = data.find((t) => t[config.keyAttr] === curNode[config.parentIdAttr]);
            if (item) {
                result.push(item);
            }
            curNode = item;
        }
        return result;
    },
    /**
     * getDescendants
     * @description - 获取子孙
     */
    getDescendants(data, node, config) {
        function loop(n) {
            const children = data.filter((t) => t[config.parentIdAttr] === n[config.keyAttr]);
            children.forEach((t) => {
                result.push(t);
                loop(t);
            });
        }
        const result = [];
        loop(node);
        return result;
    },
    /**
     * completionIncompleteFlatArr
     * @description 补残缺的FlatArr
     */
    completionIncompleteFlatArr(treeFlatNodes, incompleteTreeFlatNodes, config) {
        let set = new Set();
        incompleteTreeFlatNodes.forEach((t) => {
            const tops = this.getAncestor(treeFlatNodes, t, config);
            const tArr = [...(tops || [])].map((item) => item[config.keyAttr]);
            set = new Set([...Array.from(set), ...tArr]);
        });
        set = new Set([
            ...Array.from(set),
            ...incompleteTreeFlatNodes.map((t) => t[config.keyAttr]),
        ]);
        return this.arrayToAntdTree([...Array.from(set)].map((t) => treeFlatNodes.find((item) => item[config.keyAttr] === t)), config);
    },
    /**
     * filterTreeByFlatData
     * @description 本地过滤tree
     * @param treeFlatNodes
     * @param kw
     * @param config
     * @param filter
     */
    filterTreeByFlatData(treeFlatNodes, kw, config, filter) {
        const { filterAttr, ...arrayToAntdTreeConfig } = config;
        if (filter) {
            const arr = treeFlatNodes.filter((node) => filter?.(node));
            return this.completionIncompleteFlatArr(treeFlatNodes, arr, config);
        }
        if (kw) {
            const arr = treeFlatNodes.filter((node) => node[config.filterAttr].indexOf(kw) !== -1);
            return this.completionIncompleteFlatArr(treeFlatNodes, arr, config);
        }
        return this.arrayToAntdTree(treeFlatNodes, arrayToAntdTreeConfig);
    },
    /**
     * filterTree
     * @description
     * @param treeNodes
     * @param kw
     * @param config
     * @param filter
     */
    filterTree(treeNodes, kw, config, filter) {
        const { filterAttr, ...arrayToAntdTreeConfig } = config;
        const treeFlatNodes = this.treeToArray(treeNodes, {
            parentIdAttr: config.parentIdAttr,
            rootParentId: config.rootParentId,
        });
        if (filter) {
            const arr = treeFlatNodes.filter((node) => filter?.(node));
            return this.completionIncompleteFlatArr(treeFlatNodes, arr, config);
        }
        if (kw) {
            const arr = treeFlatNodes.filter((node) => node[config.filterAttr].indexOf(kw) !== -1);
            return this.completionIncompleteFlatArr(treeFlatNodes, arr, config);
        }
        return this.arrayToAntdTree(treeFlatNodes, arrayToAntdTreeConfig);
    },
    /**
     * findNodeByKey
     * @description - 根据keyAttr查找结点
     * @param treeData
     * @param val
     * @param config
     */
    findNodeByKey(treeData, val, config) {
        const childrenKey = config.childrenKey ?? 'children';
        function findLoop(data) {
            let result = null;
            for (let i = 0; i < data.length; i++) {
                if (data[i][config.keyAttr] === val) {
                    result = data[i];
                    break;
                }
                else {
                    if ('children' in data[i] &&
                        Array.isArray(data[i][childrenKey]) &&
                        data[i]?.[childrenKey]?.length) {
                        result = findLoop(data[i][childrenKey]);
                        if (result)
                            break;
                    }
                }
            }
            return result;
        }
        return findLoop(treeData);
    },
    /**
     * findParentNodeByKey
     * @description 根据key查找parentNode
     * @param treeData
     * @param val
     * @param config
     */
    findParentNodeByKey(treeData, val, config) {
        let parentNode;
        const keyAttr = config?.keyAttr;
        const childrenKey = config?.childrenKey ?? 'children';
        function loop(_parentNode, _nodes) {
            for (let i = 0; i < _nodes.length; i++) {
                const _node = _nodes[i];
                if (_node[keyAttr] === val) {
                    parentNode = _parentNode;
                    break;
                }
                else {
                    loop(_node, _node[childrenKey] ?? []);
                    if (parentNode) {
                        break;
                    }
                }
            }
        }
        loop(parentNode, treeData);
        return parentNode;
    },
    /**
     * transformTreeData
     * @description - 转换一个treeData为antd的TreeData
     * @param treeData
     * @param childrenAttr
     * @param onCallback
     * @return IAntdTreeNode[]
     */
    transformTreeData(treeData, childrenAttr, onCallback) {
        function loop(children) {
            const result = [];
            for (let i = 0; i < children.length; i++) {
                const node = children[i];
                node[childrenAttr || 'children'] = loop(node[childrenAttr || 'children']);
                result.push(onCallback(node));
            }
            return result;
        }
        return loop(treeData);
    },
    /**
     * getLeafNodes
     * @description 获取叶子节点
     */
    getLeafNodes(nodes = [], childrenAttr = 'children') {
        function loop(treeNodes, childrenAttr) {
            let result = [];
            for (let i = 0; i < treeNodes.length; i++) {
                const node = treeNodes[i];
                if (childrenAttr in node &&
                    Array.isArray(node[childrenAttr]) &&
                    node[childrenAttr].length > 0) {
                    // 递归子节点
                    result.push(...loop(node[childrenAttr], childrenAttr));
                }
                else {
                    // 叶子节点
                    result.push(node);
                }
            }
            return result;
        }
        return loop(nodes, childrenAttr);
    },
    /**
     * getLeafNodesByIndex
     * @description 通过索引获取叶子节点的集合
     */
    getLeafNodesByIndex(nodes = [], childrenAttr = 'children', indexAttr = 'isLeaf') {
        function loop(treeNodes, childrenAttr, leafAttr) {
            let result = [];
            for (let i = 0; i < treeNodes.length; i++) {
                const node = treeNodes[i];
                if (leafAttr in node && typeof node[leafAttr] === 'boolean' && node[leafAttr]) {
                    result.push(node);
                }
                if (childrenAttr in node && Array.isArray(node[childrenAttr])) {
                    result = [...result, ...loop(node[childrenAttr], childrenAttr, leafAttr)];
                }
            }
            return result;
        }
        return loop(nodes || [], childrenAttr || 'children', indexAttr || 'isLeaf');
    },
    /**
     * getLeafNodeByFlatData
     * @description 获取叶子节点通过拉平的数据
     * @param arr
     * @param config
     */
    getLeafNodeByFlatData(arr, config) {
        const { parentIdAttr, keyAttr } = config;
        // 获取所有的parentId
        const parentIds = arr
            .filter((t) => parentIdAttr in t && t[parentIdAttr])
            .map((t) => t[parentIdAttr]);
        // 1,2,3 parentIds
        // 1,2,3,4,5 arr
        return arr.filter((t) => !parentIds.includes(t[keyAttr]));
    },
    /**
     * getLeafNodeByFlatDataToIndex
     * @description 获取叶子节点通过索引和拉平的数据
     * @param arr
     * @param indexAttr
     */
    getLeafNodeByFlatDataToIndex(arr, indexAttr = 'isLeaf') {
        return arr.filter((t) => typeof t[indexAttr || 'isLeaf'] === 'boolean' && t[indexAttr]);
    },
    /**
     * getTreeLevel
     * @description 获取树的层级
     */
    getTreeLevel(nodes = [], keyAttr = 'key') {
        const flat = this.treeToArray(nodes, {
            parentIdAttr: 'pid',
            rootParentId: -1,
        }, keyAttr);
        const config = {
            keyAttr,
            titleAttr: keyAttr,
            parentIdAttr: 'pid',
            rootParentId: -1,
        };
        const leafNodes = this.getLeafNodeByFlatData(flat, config);
        const levels = [];
        for (let i = 0; i < leafNodes.length; i++) {
            const leafNode = leafNodes[i];
            let level = 1;
            let pid = leafNode[config.parentIdAttr];
            while (pid !== -1) {
                pid = flat.find((node) => node[keyAttr] === pid)?.[config.parentIdAttr];
                level++;
            }
            levels.push(level);
        }
        return Math.max(...levels);
    },
    /**
     * getTreeLevelByIndex
     * @description 获取树的层级通过索引
     */
    getTreeLevelByIndex(nodes = [], indexAttr = 'isLeaf', keyAttr = 'key') {
        const config = {
            parentIdAttr: 'pid',
            rootParentId: -1,
        };
        const flat = this.treeToArray(nodes, config);
        const leafNodes = this.getLeafNodeByFlatDataToIndex(flat, indexAttr);
        const levels = [];
        for (let i = 0; i < leafNodes.length; i++) {
            const leafNode = leafNodes[i];
            let level = 1;
            let pid = leafNode[config.parentIdAttr];
            while (pid !== -1) {
                pid = flat.find((node) => node[keyAttr] === pid)?.[config.parentIdAttr];
                level++;
            }
            levels.push(level);
        }
        return Math.max(...levels);
    },
    /**
     * getTreeLevelToFlat
     * @description 获取树的层级通过拉平的数据
     */
    getTreeLevelToFlat(flatArr, config) {
        const leafNodes = this.getLeafNodeByFlatData(flatArr, config);
        const levels = [];
        for (let i = 0; i < leafNodes.length; i++) {
            const leafNode = leafNodes[i];
            let level = 1;
            let pid = leafNode[config.parentIdAttr];
            while (pid !== -1) {
                pid = flatArr.find((node) => node[config.keyAttr] === pid)?.[config.parentIdAttr];
                level++;
            }
            levels.push(level);
        }
        return Math.max(...levels);
    },
    /**
     * getTreeLevelByIndexToFlat
     * @description 获取树的层级通过拉平的数据和索引
     */
    getTreeLevelByIndexToFlat(flatArr, config, indexAttr) {
        const leafNodes = this.getLeafNodeByFlatDataToIndex(flatArr, indexAttr);
        const levels = [];
        for (let i = 0; i < leafNodes.length; i++) {
            const leafNode = leafNodes[i];
            let level = 1;
            let pid = leafNode[config.parentIdAttr];
            while (pid !== -1) {
                pid = flatArr.find((node) => node[config.keyAttr] === pid)?.[config.parentIdAttr];
                level++;
            }
            levels.push(level);
        }
        return Math.max(...levels);
    },
    /**
     * getNodeLevel
     * @description 获取节点所在的level
     * @param nodes
     * @param node
     * @param keyAttr
     */
    getNodeLevel(nodes, node, keyAttr = 'key') {
        let currentLevel = -1;
        let treeLevel = this.getTreeLevel(nodes, keyAttr);
        let children = nodes;
        for (let i = 0; i < treeLevel; i++) {
            if (children.find((t) => t[keyAttr] === node[keyAttr])) {
                currentLevel = i + 1;
                break;
            }
            else {
                children = children.map((t) => t.children || []).flat();
            }
        }
        return currentLevel;
    },
    /**
     * excludeAntdTreeNodes
     * @description 排除指定节点后形成一棵树
     * @param nodes
     * @param excludeKeys
     * @param keyAttr
     */
    excludeAntdTreeNodes(nodes, excludeKeys, keyAttr = 'key') {
        const config = {
            parentIdAttr: 'pid',
            rootParentId: -1,
        };
        const flatArr = this.treeToArray(nodes, config, keyAttr);
        let _excludeKeys = [];
        for (let i = 0; i < excludeKeys.length; i++) {
            const result = loop(excludeKeys[i]);
            _excludeKeys = [..._excludeKeys, ...result];
        }
        _excludeKeys = [..._excludeKeys, ...excludeKeys];
        const omitArr = flatArr.filter((node) => !_excludeKeys.includes(node[keyAttr]));
        function loop(excludeKey) {
            const childrenKeys = flatArr
                .filter((t) => t[config.parentIdAttr] === excludeKey)
                .map((t) => t[keyAttr]);
            let excludeKeys = childrenKeys;
            for (let i = 0; i < childrenKeys.length; i++) {
                const result = loop(childrenKeys[i]);
                excludeKeys = [...excludeKeys, ...result];
            }
            return excludeKeys;
        }
        return this.completionIncompleteFlatArr(flatArr, omitArr, {
            keyAttr,
            titleAttr: 'title',
            parentIdAttr: config.parentIdAttr,
            rootParentId: config.rootParentId,
        });
    },
    /**
     * excludeAntdSelectTreeNodes
     * @description 排除指定节点后形成一棵树
     * @param nodes
     * @param excludeKeys
     * @param keyAttr
     */
    excludeAntdSelectTreeNodes(nodes, excludeKeys, keyAttr = 'key') {
        const config = {
            parentIdAttr: 'pid',
            rootParentId: -1,
        };
        const flatArr = this.treeToArray(nodes, config, keyAttr);
        let _excludeKeys = [];
        for (let i = 0; i < excludeKeys.length; i++) {
            const result = loop(excludeKeys[i]);
            _excludeKeys = [..._excludeKeys, ...result];
        }
        _excludeKeys = [..._excludeKeys, ...excludeKeys];
        const omitArr = flatArr.filter((node) => !_excludeKeys.includes(node[keyAttr]));
        function loop(excludeKey) {
            const childrenKeys = flatArr
                .filter((t) => t[config.parentIdAttr] === excludeKey)
                .map((t) => t[keyAttr]);
            let excludeKeys = childrenKeys;
            for (let i = 0; i < childrenKeys.length; i++) {
                const result = loop(childrenKeys[i]);
                excludeKeys = [...excludeKeys, ...result];
            }
            return excludeKeys;
        }
        return this.completionIncompleteFlatArr(flatArr, omitArr, {
            keyAttr,
            titleAttr: 'title',
            parentIdAttr: config.parentIdAttr,
            rootParentId: config.rootParentId,
        });
    },
};
export default TreeUtil;
